# Topic 23: Statistical reporting and reproducible analysis (rmarkdown, knitr, broom, gt)
source("common/helpers.R"); start_topic("23_reproducible_reporting")
need("rmarkdown", "knitr", "broom")

h("WORKED EXAMPLE: the reproducibility checklist")
for (item in c("Fixed random seed", "Raw data kept unchanged in data/", "All steps in code (no manual edits)",
               "Package versions recorded (sessionInfo)", "Outputs regenerated by one command", "Interpretation written next to results"))
  cat(" [x]", item, "\n")

h("TABLE WITH gt (publication-style table)")
df <- load_data("students.csv")
by_method <- aggregate(exam_score ~ method, df, function(v) c(n = length(v), mean = mean(v), sd = sd(v)))
by_method <- do.call(data.frame, by_method)
names(by_method) <- c("method", "n", "mean", "sd")
if (opt("gt")) {
  g <- gt::gt(by_method)
  g <- gt::fmt_number(g, columns = c("mean", "sd"), decimals = 2)
  g <- gt::tab_header(g, title = "Exam score by teaching method")
  gt::gtsave(g, file.path(normalizePath(OUT), "r_table_by_method.html"))
  cat("Saved r_table_by_method.html\n")
} else print(by_method)

h("RENDER THE R MARKDOWN REPORT")
rmd <- file.path("topics", "23_reproducible_reporting", "r", "report.Rmd")
if (rmarkdown::pandoc_available()) {
  rmarkdown::render(rmd, output_dir = OUT, output_file = "report_r.html", knit_root_dir = getwd(), quiet = TRUE)
  cat("Wrote", file.path(OUT, "report_r.html"), "\n")
} else {
  knitr::knit(rmd, output = file.path(OUT, "report_r.md"), quiet = TRUE)
  cat("Pandoc not found: wrote Markdown only ->", file.path(OUT, "report_r.md"), "\n")
}

h("ENVIRONMENT RECORD"); print(sessionInfo())

h("INTERPRETATION")
cat("- A reproducible report ties code, tables, figures and conclusions together so anyone can regenerate it.\n")
cat("- Numbers in the text are inserted by code (inline `r ...` chunks), so new data updates every sentence automatically.\n")
end_topic()
